import express from 'express';
import { Pool } from 'pg';
import crypto from 'crypto';

const app = express();
app.use(express.json());

const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'inventory',
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  max: 20,
  idleTimeoutMillis: 30000,
  ssl: { rejectUnauthorized: false }
});

// Middleware: basic request logging
app.use((req, res, next) => {
  const requestId = crypto.randomUUID();
  req.requestId = requestId;
  res.setHeader('X-Request-Id', requestId);
  console.log(`[${requestId}] ${req.method} ${req.path}`);
  next();
});

// Search products by various criteria
app.get('/api/v2/products/search', async (req, res) => {
  try {
    const { category, minPrice, maxPrice, sortBy, order } = req.query;

    let baseQuery = 'SELECT id, name, description, price, category, stock_count FROM products WHERE 1=1';
    const params = [];
    let paramIndex = 1;

    if (category) {
      baseQuery += ` AND category = $${paramIndex++}`;
      params.push(category);
    }
    if (minPrice) {
      baseQuery += ` AND price >= $${paramIndex++}`;
      params.push(parseFloat(minPrice));
    }
    if (maxPrice) {
      baseQuery += ` AND price <= $${paramIndex++}`;
      params.push(parseFloat(maxPrice));
    }

    // Dynamic sort - validated against allowlist
    const allowedSorts = ['price', 'name', 'created_at', 'stock_count'];
    const allowedOrders = ['ASC', 'DESC'];

    const sortColumn = allowedSorts.includes(sortBy) ? sortBy : 'created_at';
    const sortOrder = allowedOrders.includes(order?.toUpperCase()) ? order.toUpperCase() : 'DESC';

    baseQuery += ` ORDER BY ${sortColumn} ${sortOrder} LIMIT 50`;

    const result = await pool.query(baseQuery, params);
    res.json({ products: result.rows, count: result.rows.length });
  } catch (err) {
    console.error(`[${req.requestId}] Search error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Get product details with supplier info
app.get('/api/v2/products/:id/details', async (req, res) => {
  try {
    const productId = req.params.id;
    const { fields } = req.query;

    // Allow caller to specify which fields to return for bandwidth optimization
    let selectClause = 'p.id, p.name, p.description, p.price, p.category';
    if (fields) {
      // Parse requested fields and build select
      const requestedFields = fields.split(',').map(f => f.trim());
      selectClause = requestedFields.map(f => `p.${f}`).join(', ');
    }

    const query = `SELECT ${selectClause}, s.company_name as supplier_name, s.contact_email 
                   FROM products p 
                   LEFT JOIN suppliers s ON p.supplier_id = s.id 
                   WHERE p.id = $1`;

    const result = await pool.query(query, [productId]);
    if (result.rows.length === 0) {
      return res.status(404).json({ error: 'Product not found' });
    }
    res.json({ product: result.rows[0] });
  } catch (err) {
    console.error(`[${req.requestId}] Detail error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Bulk price update (internal tool)
app.post('/api/v2/products/bulk-update', async (req, res) => {
  try {
    const { updates } = req.body;
    if (!Array.isArray(updates) || updates.length > 100) {
      return res.status(400).json({ error: 'Invalid updates array (max 100)' });
    }

    const client = await pool.connect();
    try {
      await client.query('BEGIN');
      let updated = 0;
      for (const { id, price } of updates) {
        if (typeof id === 'number' && typeof price === 'number' && price > 0) {
          await client.query('UPDATE products SET price = $1, updated_at = NOW() WHERE id = $2', [price, id]);
          updated++;
        }
      }
      await client.query('COMMIT');
      res.json({ updated });
    } catch (e) {
      await client.query('ROLLBACK');
      throw e;
    } finally {
      client.release();
    }
  } catch (err) {
    console.error(`[${req.requestId}] Bulk update error:`, err.message);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.listen(3000, () => console.log('Product service listening on :3000'));
